SET TIME ZONE 'UTC';
SELECT m.numero_pedido,count(*) FILTER(WHERE p.tipo_evento='COBRANCA' AND p.status='APROVADO') quantidade_cobrancas_aprovadas,count(DISTINCT p.meio_pagamento) FILTER(WHERE p.tipo_evento='COBRANCA' AND p.status='APROVADO') quantidade_meios,sum(p.valor) FILTER(WHERE p.tipo_evento='COBRANCA' AND p.status='APROVADO') valor_cobrado_aprovado FROM vw_pedidos_metricas m JOIN pagamentos p USING(pedido_id) WHERE m.status_logistico<>'CANCELADO' GROUP BY m.pedido_id,m.numero_pedido,m.receita_mercadoria_pre_devolucao,m.frete_cobrado_elegivel HAVING count(*) FILTER(WHERE p.tipo_evento='COBRANCA' AND p.status='APROVADO')=2 AND count(DISTINCT p.meio_pagamento) FILTER(WHERE p.tipo_evento='COBRANCA' AND p.status='APROVADO')=2 AND sum(p.valor) FILTER(WHERE p.tipo_evento='COBRANCA' AND p.status='APROVADO')=m.receita_mercadoria_pre_devolucao+m.frete_cobrado_elegivel ORDER BY m.numero_pedido;
